export function assertPublicCrisisQuantitative(svg,lang,kind){
 const{nodes}=inspectPublicCrisisSvg(svg,lang,kind),rects=nodes.filter(n=>jlrTag(n)==='rect').map(jlrAttrs),texts=nodes.filter(n=>jlrTag(n)==='text').map(jlrText),near=(a,b)=>assert.ok(Math.abs(Number(a)-b)<=.00051);
 if(kind==='decision'){const cards=rects.filter(a=>a.y==='288'&&a.height==='425');assert.deepEqual(cards.map(a=>[a.x,a.width]),[['48','430'],['522','430']]);assert.ok(texts.includes(lang==='fr'?'LA RÉGULARITÉ EST EN CAUSE':'THE ISSUE IS REGULARITY'));}
 if(kind==='guarantee'){const bars=rects.filter(a=>a.y==='987');assert.equal(bars.length,2);near(bars[0].x,48);near(bars[0].width,904*.8);near(bars[1].x,48+904*.8);near(bars[1].width,904*.2);assert.equal((1500-300)/1500*100,80);for(const value of(lang==='fr'?['80 %','20 %','1,2 Md£ couverts','0,3 Md£ retenus']:['80%','20%','£1.2bn covered','£0.3bn retained']))assert.ok(texts.includes(value));}
 if(kind==='financing'){const blocks=rects.filter(a=>a.width==='198'&&a.height==='72'&&!a.fill.startsWith('url('));assert.equal(blocks.length,11);assert.deepEqual(blocks.map(a=>[a.x,a.y]),[['80','363'],['278','363'],['476','363'],['80','915'],['278','915'],['476','915'],['674','915'],['80','1735'],['278','1735'],['476','1735'],['674','1735']]);assert.equal(1000-1000,0);assert.equal(1000+500+500,2000);assert.ok(texts.includes(lang==='fr'?'1 000 empruntés − 1 000 remboursés = 0':'1,000 borrowed − 1,000 repaid = 0'));}
 if(kind==='monitoring'){const data=JSON.parse(metadataText(nodes.find(n=>jlrTag(n)==='metadata'&&jlrAttrs(n).id.endsWith('-data'))));assert.equal(data.financial_relationships.length,4);assert.equal(data.monitoring_relationships.length,2);assert.equal(data.named_intermediaries.length,3);assert.equal(data.quantitative_encoding,null);}
}


// Conservative glyph envelopes measured with the pinned supplied fonts in both semantic themes,
// at 350, 600 and 1000 px. Rounded outwards, with one extra native SVG unit on every side.
